<template><div v-if="visible" class="announcement-modal-overlay"><div class="announcement-modal"><button class="announcement-close" @click="close">&times;</button><h2>网站公告</h2><div class="announcement-content"><div class="announcement-panel"><p :class="['announcement-text', { 'announcement-loading': loading }]">{{ loading?'加载中...':(content||'暂无公告内容') }}</p></div><p v-if="error" class="announcement-error">{{ error }}</p></div><label v-if="user?.uid" class="announcement-checkbox"><input v-model="skip" type="checkbox"><span>在本次登录有效期内不再弹出</span></label><button class="announcement-btn" @click="close">确认</button></div></div></template>
<script setup>import { computed, ref, watch } from 'vue'; import {useAuth} from '../contexts/app'; import {announcementService} from '../services/announcementService'; import './AnnouncementModal.css'; const {user,token}=useAuth(); const visible=ref(false),content=ref(''),loading=ref(true),error=ref(''),skip=ref(false); const key=computed(()=>user.value?.uid?`announcement_hidden_until_${user.value.uid}`:'announcement_hidden_until_guest'); const load=async()=>{loading.value=true;error.value='';const hidden=Number(localStorage.getItem(key.value)||0);if(hidden>Date.now()){visible.value=false;loading.value=false;return}localStorage.removeItem(key.value);visible.value=true;try{const d=await announcementService.getAnnouncement();content.value=d.content||'';visible.value=Boolean(content.value.trim())}catch(e){error.value=e.response?.data?.detail||'公告加载失败';visible.value=true}finally{loading.value=false}};watch(key,load,{immediate:true});const close=()=>{if(skip.value&&user.value?.uid){const p=token.value?.split('.')[1];try{const normalized=p.replace(/-/g,'+').replace(/_/g,'/');const d=JSON.parse(atob(normalized.padEnd(Math.ceil(normalized.length/4)*4,'=')));if(typeof d.exp==='number')localStorage.setItem(key.value,String(d.exp*1000))}catch{}}visible.value=false};</script>
